const WB={base:Vibe.base,token:Vibe.token,projectId:sessionStorage.getItem('wb-project')||'',projects:[],status:null,job:null,cursor:0,timer:null,tab:'activity',events:[]};
async function wbApi(endpoint,options={}){const response=await fetch(WB.base+'/api'+endpoint,{...options,headers:{'Content-Type':'application/json','Authorization':'Bearer '+WB.token,...options.headers},signal:AbortSignal.timeout(25000)});let result;try{result=await response.json();}catch{throw Error('Local companion returned an invalid response.');}if(!response.ok)throw Error(result.error||'Local companion request failed.');return result;}
function wbMessage(message,error=false){const e=document.querySelector('#build-message');if(e){e.textContent=message;e.classList.toggle('error',error);}else toast(message);}
async function builder(){clearInterval(WB.timer);$('#main').innerHTML=shell('Build something real.','Create a project, run Codex, review the result, and keep iterating.',`<span id="engine-badge" class="tag">Checking Codex…</span>`)+`<section id="engine-connect" class="panel connection-panel"><p>Checking your local Codex engine…</p></section><div id="build-message" role="status" aria-live="polite"></div><div id="build-workspace"></div>`;await wbConnect();}
async function wbConnect(){try{WB.token=Vibe.token;WB.status=await wbApi('/status');$('#engine-badge').textContent=WB.status.providers.codex.signedIn?'● Codex connected':'Codex sign-in required';$('#engine-badge').classList.toggle('connected',WB.status.providers.codex.signedIn);$('#engine-connect').innerHTML=`<div><h3>Your Codex build engine</h3><p class="subtle">${WB.status.providers.codex.signedIn?'Signed in with the local ChatGPT subscription.':'Run codex login on this computer, then refresh.'}</p></div><div class="actions"><button id="refresh-engine">Refresh status</button><a class="button" href="/practice/">Open Practice ↗</a></div>`;$('#refresh-engine').onclick=()=>wbConnect();wbMessage('');await wbLoadProjects();}catch(e){$('#engine-badge').textContent='Engine unavailable';wbMessage(e.message.includes('fetch')?'Start Start-Platform.ps1, then open http://127.0.0.1:4173/account/.':e.message,true);}}
async function wbLoadProjects(){const result=await wbApi('/projects');WB.projects=result.projects;if(!WB.projects.some(p=>p.id===WB.projectId))WB.projectId=WB.projects[0]?.id||'';wbWorkspace();}
function wbWorkspace(){const current=WB.projects.find(p=>p.id===WB.projectId);$('#build-workspace').innerHTML=`<div class="builder-layout"><section class="panel project-list"><div class="session-head"><h2>Projects</h2><span class="tag">${WB.projects.length}</span></div><button class="primary" id="create-from-brief">Create from current brief</button><a class="text-link" href="#project" style="display:block;margin:10px 0">Edit your project brief ↗</a><button id="create-demo">Try a small demo</button><div class="project-items">${WB.projects.map(p=>`<button class="project-item ${p.id===WB.projectId?'selected':''}" data-project="${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${p.activeJob?'● Running':'Local Git project'}</small></button>`).join('')||'<p class="note">Your projects will appear here.</p>'}</div><p class="note">Projects are saved in:<br><span class="project-path">${esc(WB.status.projectsRoot)}</span></p></section><section class="build-detail">${current?`<div class="panel"><div class="session-head"><div><h2>${esc(current.name)}</h2><a href="/practice/?project=${esc(current.id)}">Open in Practice ↗</a><span class="subtle project-path">${esc(current.directory)}</span></div><span class="tag" id="job-state">Ready</span></div><div class="provider-fields"><div class="field"><label for="build-provider">Coding provider</label><select id="build-provider"><option value="codex">Codex · ChatGPT subscription</option></select></div><div class="field"><label for="build-model">Model (optional)</label><input id="build-model" placeholder="Provider default" maxlength="150"></div></div><div id="provider-settings"></div><label class="task-label" for="build-task">What should the agent build or change?</label><textarea id="build-task" placeholder="Describe the next small change…">Implement the first milestone in PROJECT.md. Verify the result and update TASKS.md.</textarea><div class="actions" style="margin-top:12px"><button id="run-build" class="primary">${icon('code')} Build with agent</button><button id="install-packages">Install packages</button><button id="run-checks">Run project checks</button><button id="stop-build" disabled>Stop</button></div><p class="note">Codex runs with the local signed-in subscription. Review changes and checks before using the result.</p></div><div class="build-tabs" role="tablist" aria-label="Project views">${['activity','files','changes','preview','history'].map(t=>`<button role="tab" aria-selected="${WB.tab===t}" data-build-tab="${t}" class="${WB.tab===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="panel build-output" id="build-output" role="tabpanel"></div>`:'<div class="empty"><h2>Your next project starts here.</h2><p>Create a project from your current brief, or try the small demo to test the workflow.</p></div>'}</section></div>`;$('#create-from-brief').onclick=()=>wbCreate(false);$('#create-demo').onclick=()=>wbCreate(true);document.querySelectorAll('[data-project]').forEach(e=>e.onclick=()=>{clearInterval(WB.timer);WB.projectId=e.dataset.project;sessionStorage.setItem('wb-project',WB.projectId);WB.job=null;WB.events=[];WB.cursor=0;wbWorkspace();});if(!current)return;$('#build-provider').onchange=wbProvider;wbProvider();$('#run-build').onclick=wbStart;$('#run-checks').onclick=wbVerify;$('#install-packages').onclick=wbInstall;$('#stop-build').onclick=async()=>{try{if(WB.job)await wbApi('/jobs/'+WB.job.id+'/cancel',{method:'POST',body:'{}'});}catch(e){wbMessage(e.message,true);}};document.querySelectorAll('[data-build-tab]').forEach(e=>e.onclick=()=>{WB.tab=e.dataset.buildTab;document.querySelectorAll('[data-build-tab]').forEach(b=>{b.classList.toggle('active',b===e);b.setAttribute('aria-selected',String(b===e));});wbView();});wbView();if(current.activeJob&&(!WB.job||WB.job.id!==current.activeJob))wbWatch(current.activeJob);else if(WB.job)wbJobControls();}
function wbProvider(){const provider=$('#build-provider').value,keyMode=['openai','anthropic','compatible'].includes(provider);$('#provider-settings').innerHTML=(provider==='claude'&&!WB.status.providers.claude.signedIn?'<p class="provider-note">Claude Code is installed, but needs your subscription sign-in. Run <code>Connect-Claude.ps1</code>, complete the browser login, then click Refresh status. The workbench does not collect your Claude password.</p>':'')+(provider==='codex'&&!WB.status.providers.codex.signedIn?'<p class="provider-note">Run <code>codex login</code> in your terminal, then refresh status.</p>':'')+(keyMode?`<div class="field"><label for="provider-key">${provider==='anthropic'?'Anthropic':'OpenAI or compatible provider'} API key</label><input type="password" id="provider-key" autocomplete="off" spellcheck="false" placeholder="Used for this build only"><p class="note">Sent directly to your paired local companion. Never stored in browser backups, project files, or job history. API usage is billed separately from subscriptions.</p></div>`:'')+(provider==='compatible'?'<div class="field" style="margin-top:12px"><label for="provider-url">Responses API base URL</label><input type="url" id="provider-url" placeholder="https://provider.example/v1"><p class="note">The endpoint must support the OpenAI Responses API used by Codex. Chat Completions-only endpoints are not supported.</p></div>':'');$('#build-model').placeholder=provider==='compatible'?'Required: provider model ID':'Provider default';}
async function wbCreate(demo){const button=demo?$('#create-demo'):$('#create-from-brief');button.disabled=true;try{const brief=demo?{name:'Workbench Task Demo',goal:'A small task manager that proves the workbench can build a real project.',audience:'A person managing a short task list',features:'Add a task\nMark tasks complete\nDelete a task\nPersist tasks locally\nShow empty and validation states',stack:'Plain HTML, CSS, and JavaScript. No dependencies. Use relative asset paths. Provide a Node package.json check script using node --check app.js.',constraints:'No external network requests, images, generated artwork, authentication, or paid services. Keep all files in this project.',verify:'Add, complete, delete, and reload tasks. Keyboard accessible and responsive.'}:state.brief;const p=await wbApi('/projects',{method:'POST',body:JSON.stringify({brief:{...brief,edition:Vibe.user.defaultEdition}})});WB.projectId=p.id;sessionStorage.setItem('wb-project',p.id);WB.job=null;WB.events=[];WB.cursor=0;WB.tab='activity';await wbLoadProjects();wbMessage('Project created. Choose a provider and click Build with agent.');}catch(e){wbMessage(e.message,true);}finally{if(button.isConnected)button.disabled=false;}}
async function wbStart(){const button=$('#run-build');button.disabled=true;try{const key=$('#provider-key')?.value||'';const input={provider:$('#build-provider').value,model:$('#build-model').value,baseUrl:$('#provider-url')?.value||'',key,task:$('#build-task').value};if($('#provider-key'))$('#provider-key').value='';WB.job=await wbApi('/projects/'+WB.projectId+'/build',{method:'POST',body:JSON.stringify(input)});input.key='';WB.tab='activity';document.querySelector('[data-build-tab="activity"]').click();wbMessage('Build started. You can review the live activity below.');wbWatch(WB.job.id);}catch(e){button.disabled=false;wbMessage(e.message,true);}}
async function wbVerify(){try{WB.job=await wbApi('/projects/'+WB.projectId+'/verify',{method:'POST',body:'{}'});WB.tab='activity';document.querySelector('[data-build-tab="activity"]').click();wbWatch(WB.job.id);}catch(e){wbMessage(e.message,true);}}
function wbJobControls(){const active=WB.job&&['queued','running','cancelling'].includes(WB.job.status);if($('#job-state'))$('#job-state').textContent=WB.job?WB.job.status:'Ready';if($('#run-build'))$('#run-build').disabled=!!active;if($('#run-checks'))$('#run-checks').disabled=!!active;if($('#install-packages'))$('#install-packages').disabled=!!active;if($('#stop-build'))$('#stop-build').disabled=!active||WB.job.status==='cancelling';}
function wbWatch(id){clearInterval(WB.timer);WB.cursor=0;WB.events=[];const projectId=WB.projectId;const poll=async()=>{if(location.hash!=='#build'||projectId!==WB.projectId){clearInterval(WB.timer);return;}try{const j=await wbApi('/jobs/'+id+'?after='+WB.cursor);WB.job=j;for(const e of j.events){WB.events.push(e);WB.cursor=Math.max(WB.cursor,e.seq);}wbJobControls();if(WB.tab==='activity')wbActivity();if(!['running','queued','cancelling'].includes(j.status)){clearInterval(WB.timer);wbMessage(j.status==='completed'?'Finished. Review the files and changes, run checks, and open the preview.':`Job ${j.status}. Review the activity for details.`,j.status==='failed');WB.projects= (await wbApi('/projects')).projects;}}catch(e){clearInterval(WB.timer);wbMessage('Connection lost: '+e.message+'. Reconnect to recover the job history.',true);}};poll();WB.timer=setInterval(poll,1600);}
function wbActivity(){const out=$('#build-output');if(!out)return;const opened=new Set([...out.querySelectorAll('details[open][data-event]')].map(e=>e.dataset.event));out.innerHTML=WB.events.length?`<div class="activity-list">${WB.events.map(e=>`<details data-event="${e.seq}" class="activity-entry ${e.kind==='error'?'error':''}" ${opened.has(String(e.seq))||['assistant','error','status'].includes(e.kind)?'open':''}><summary class="activity-kind">${esc(e.kind)} <time>${esc(new Date(e.time).toLocaleTimeString())}</time></summary><pre>${esc(e.text)}</pre></details>`).join('')}</div>`:'<div class="empty">Build activity will appear here. Jobs continue while you browse the playbooks.</div>';}
async function wbView(){const out=$('#build-output');if(!out)return;if(WB.tab==='activity'){wbActivity();return;}out.innerHTML='<p class="subtle">Loading project…</p>';const tab=WB.tab,id=WB.projectId;try{if(tab==='files'){const result=await wbApi('/projects/'+id+'/files');if(WB.tab!==tab||WB.projectId!==id)return;out.innerHTML=`<div class="file-browser"><div class="file-list">${result.files.map(f=>`<button data-file="${esc(f.path)}">${esc(f.path)} <small>${f.size.toLocaleString()} B</small></button>`).join('')||'<p>No files yet.</p>'}</div><div><h3 id="file-title">Select a file</h3><pre id="file-content" class="file-content">Choose a project file to inspect its source.</pre></div></div>`;document.querySelectorAll('[data-file]').forEach(e=>e.onclick=async()=>{try{const result=await wbApi('/projects/'+id+'/files?path='+encodeURIComponent(e.dataset.file));$('#file-title').textContent=e.dataset.file;$('#file-content').textContent=result.text;}catch(e){wbMessage(e.message,true);}});}else if(tab==='changes'){const result=await wbApi('/projects/'+id+'/diff');if(WB.tab!==tab||WB.projectId!==id)return;out.innerHTML=`<h3>Changes since project creation</h3><pre class="file-content"></pre><h3 style="margin-top:20px">New files</h3><pre id="new-files" class="file-content"></pre><h3 style="margin-top:20px">Tracked file diff</h3><pre id="file-diff" class="file-content"></pre>`;out.querySelector('pre').textContent=result.summary||'No tracked changes.';$('#new-files').textContent=result.untracked.join('\n')||'No new files.';$('#file-diff').textContent=result.patch||'Read newly created files in the Files tab.';}else if(tab==='preview'){const result=await wbApi('/projects/'+id+'/preview');if(WB.tab!==tab||WB.projectId!==id)return;if(!result.available){out.innerHTML=`<div class="empty">${esc(result.message)}</div>`;return;}out.innerHTML=`<div class="session-head"><p class="subtle">Static project preview · isolated port 4184</p><a class="button" href="${esc(result.url)}" target="_blank" rel="noopener">Open preview ↗</a></div><iframe title="${esc(WB.projects.find(p=>p.id===id)?.name||'Project')} preview" src="${esc(result.url)}" sandbox="allow-scripts allow-forms allow-same-origin" class="project-preview"></iframe>`;}else if(tab==='history'){const result=await wbApi('/projects/'+id+'/jobs');if(WB.tab!==tab||WB.projectId!==id)return;out.innerHTML=result.jobs.slice().reverse().map(j=>`<button class="row" data-job="${esc(j.id)}"><div><strong>${esc(j.kind)} · ${esc(j.provider)}</strong><small>${esc(new Date(j.createdAt).toLocaleString())}</small></div><span class="tag" style="margin-left:auto">${esc(j.status)}</span></button>`).join('')||'<div class="empty">No jobs for this project yet.</div>';document.querySelectorAll('[data-job]').forEach(e=>e.onclick=()=>{document.querySelector('[data-build-tab="activity"]').click();wbWatch(e.dataset.job);});}}catch(e){if(WB.tab===tab&&WB.projectId===id)out.innerHTML='<div class="empty">'+esc(e.message)+'</div>';}}
async function wbInstall(){try{WB.job=await wbApi('/projects/'+WB.projectId+'/install',{method:'POST',body:'{}'});WB.tab='activity';document.querySelector('[data-build-tab="activity"]').click();wbWatch(WB.job.id);}catch(e){wbMessage(e.message,true);}}

